<script>
document.addEventListener('DOMContentLoaded',function(){const type=document.getElementById('investmentClass'),category=document.getElementById('investmentCategory');const options={capital:{land:'Land',layer_house:'Layer House (Pen)',battery_cages:'Battery Cages',borehole_tanks:'Boreholes & Overhead Tanks',generator_solar:'Generator / Solar',rubber_hose_bowls:'Rubber Hose & Bowls',office_utilities:'Office Utilities',egg_crates:'Egg Crates'},working_capital:{point_of_cage_birds:'Point-of-cage Birds',feeding_14_25_weeks:'Feeding (14-25 Weeks)',medication:'Medication',vaccination:'Vaccination',personnel:'Personnel'}};function fill(){category.innerHTML='';Object.entries(options[type.value]||{}).forEach(([value,text])=>category.add(new Option(text,value)));}type?.addEventListener('change',fill);fill();const flock=document.getElementById('productionFlock'),birds=document.getElementById('openingBirds');flock?.addEventListener('change',()=>birds.value=flock.selectedOptions[0]?.dataset.birds||'');document.querySelectorAll('[data-journal-toggle]').forEach(function(toggle){const accounts=toggle.closest('.farm-form').querySelector('[data-journal-accounts]');toggle.addEventListener('change',function(){accounts.classList.toggle('d-none',!toggle.checked);accounts.querySelectorAll('select').forEach(select=>select.required=toggle.checked);});});});
</script>
